sparql:
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
SELECT ?film ?filmLabel(MIN(?date) AS ?earliestDirectorDeath) WHERE {
  VALUES ?film {
    <http://dbpedia.org/resource/Johnny,_You're_Wanted> dbr:The_Heart_of_Ezra_Greer
  }
  ?film(dbo:director | dbp:director) ?director .
  OPTIONAL {
    {
      ?director dbo:deathDate ?d .
      BIND(xsd:date(?d) AS ?date)
    } UNION {
      ?director dbo:wikiPageRedirects ?dres .
      ?dres dbo:deathDate ?d2 .
      BIND(xsd:date(?d2) AS ?date)
    } UNION {
      ?director owl:sameAs ?dres2 .
      ?dres2 dbo:deathDate ?d3 .
      BIND(xsd:date(?d3) AS ?date)
    }
  }
  OPTIONAL {
    ?film rdfs:label ?filmLabel .
    FILTER(lang(?filmLabel) = 'en')
  }
}
GROUP BY ?film ?filmLabel
ORDER BY ?earliestDirectorDeath
LIMIT 1

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?y1 ?y2 ?lev_bd ?c_abs WHERE {
  OPTIONAL {
    dbr:Levon_Julfalakyan dbo:birthDate ?lev_bd .
    BIND(YEAR(?lev_bd) AS ?y1)
  }
  OPTIONAL {
    dbr:Charlotte_Spurkeland dbo:abstract ?c_abs .
    FILTER(langMatches(lang(?c_abs) , "en"))
    .
    BIND(xsd:integer(REPLACE(STRAFTER(STR(?c_abs) , "born ") , '.*?(\\d{4}).*' , '$1')) AS ?y2)
  }
}

