SELECT ?film ?filmLabel ?director ?directorLabel ?bd WHERE {
  VALUES ?film {
    <http://dbpedia.org/resource/Sabas,_ang_barbaro> dbr:Passage_to_Zarahemla
  }
  ?film ?dirProp ?director .
  FILTER(?dirProp IN(dbo:director , dbp:director))
  OPTIONAL {
    ?director dbo:birthDate ?birthDate .
  }
  OPTIONAL {
    ?director dbp:birth_date ?birthDate2 .
  }
  OPTIONAL {
    ?director dbp:birthDate ?birthDate3 .
  }
  OPTIONAL {
    ?director dbo:abstract ?abs
    FILTER(lang(?abs) = 'en')
  }
  BIND(COALESCE(?birthDate , ?birthDate2 , ?birthDate3) AS ?bd1)
  BIND(IF(BOUND(?bd1) , ?bd1 , IF(REGEX(?abs , "born.*(\\d{4})" , "i") , xsd:date(CONCAT(REPLACE(?abs , ".*born.*(\\d{4}).*" , "$1") , "-01-01")) , xsd:date("0001-01-01"))) AS ?bd)
  OPTIONAL {
    ?film rdfs:label ?filmLabel
    FILTER(lang(?filmLabel) = 'en')
  }
  OPTIONAL {
    ?director rdfs:label ?directorLabel
    FILTER(lang(?directorLabel) = 'en')
  }
}
ORDER BY DESC(?bd)
LIMIT 1

